-- GnuCash 5.x-shaped SQLite fixture book for fin-app tests.
-- post_date format: YYYYMMDDHHMMSS (neutral time 10:59:00 UTC → …105900).
-- Never use a user's real GnuCash book in tests.

PRAGMA foreign_keys = ON;

CREATE TABLE gnclock (
    Hostname varchar(255),
    PID int
);

CREATE TABLE versions (
    table_name    text(50),
    table_version integer
);

CREATE TABLE commodities (
    guid         CHAR(32) PRIMARY KEY NOT NULL,
    namespace    text(2048) NOT NULL,
    mnemonic     text(2048) NOT NULL,
    fullname     text(2048),
    cusip        text(2048),
    fraction     integer NOT NULL,
    quote_flag   integer NOT NULL,
    quote_source text(2048),
    quote_tz     text(2048)
);

CREATE TABLE books (
    guid                CHAR(32) PRIMARY KEY NOT NULL,
    root_account_guid   CHAR(32) NOT NULL,
    root_template_guid  CHAR(32) NOT NULL
);

CREATE TABLE accounts (
    guid            CHAR(32) PRIMARY KEY NOT NULL,
    name            text(2048) NOT NULL,
    account_type    text(2048) NOT NULL,
    commodity_guid  CHAR(32) NOT NULL,
    commodity_scu   integer NOT NULL,
    non_std_scu     integer NOT NULL,
    parent_guid     CHAR(32),
    code            text(2048),
    description     text(2048),
    hidden          integer NOT NULL,
    placeholder     integer NOT NULL
);

CREATE TABLE transactions (
    guid          CHAR(32) PRIMARY KEY NOT NULL,
    currency_guid CHAR(32) NOT NULL,
    num           text(2048) NOT NULL,
    post_date     text(14) NOT NULL,
    enter_date    text(14) NOT NULL,
    description   text(2048)
);

CREATE TABLE splits (
    guid             CHAR(32) PRIMARY KEY NOT NULL,
    tx_guid          CHAR(32) NOT NULL,
    account_guid     CHAR(32) NOT NULL,
    memo             text(2048) NOT NULL,
    action           text(2048) NOT NULL,
    reconcile_state  text(1) NOT NULL,
    reconcile_date   text(14) NOT NULL,
    value_num        integer NOT NULL,
    value_denom      integer NOT NULL,
    quantity_num     integer NOT NULL,
    quantity_denom   integer NOT NULL,
    lot_guid         CHAR(32)
);

CREATE TABLE slots (
    id                  integer PRIMARY KEY AUTOINCREMENT NOT NULL,
    obj_guid            CHAR(32) NOT NULL,
    name                text(4096) NOT NULL,
    slot_type           integer NOT NULL,
    int64_val           integer,
    string_val          text(4096),
    double_val          real,
    timespec_val        CHAR(14),
    guid_val            CHAR(32),
    numeric_val_num     integer,
    numeric_val_denom   integer,
    gdate_val           date
);

